#!/usr/bin/env bash
k="$HOST_KEY_DIR"; abs=no; case "$k" in /*) abs=yes;; esac; d=no; [ -d "$k" ] && d=yes
echo "docker-build abs=$abs isdir=$d dir=$k" >> "$FAKE_BIN_LOG"
mkdir -p "$(dirname "$0")/../launcher/app/build/outputs/apk/release"
: > "$(dirname "$0")/../launcher/app/build/outputs/apk/release/app-release.apk"
exit ${STUB_RC:-0}

